ThemeSelection = {	
	init: function(app, container){
        app = app || session.app;
        container = container || $(".component[name=ThemeSelection]");	

       var themes = new Array();
       for(var i in app.Config.Themes) { themes.push({ name: i, value: i }); }

		$('[name=defaultFilters]', container).kendoDropDownList({
			dataSource: themes,
			dataTextField: 'name',
			dataValueField: 'value',
			value: session.theme,
			change: function (e) {
				setQueryParameter('theme', e.sender.value());
			}
		});
	}
}
